#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    char board[8][8];

    for (int i = 0; i < 8; ++i)
        for (int j = 0; j < 8; ++j)
            cin >> board[i][j];

    int white = 8, black = 8;

    for (int col = 0; col < 8; ++col) {
        for (int row = 0; row < 8; ++row) {
            if (board[row][col] != '.') {
                if (board[row][col] == 'W')
                    white = min(white, row);
                break;
            }
        }

        for (int row = 7; row >= 0; --row) {
            if (board[row][col] != '.') {
                if (board[row][col] == 'B')
                    black = min(black, 7 - row);
                break;
            }
        }
    }

    cout << (white <= black ? 'A' : 'B');
    return 0;
}

